$('#buildBtn').onclick=openBuild;$('#editBtn').onclick=()=>{editMode=!editMode;$('#editBtn').classList.toggle('selected',editMode);notify(editMode?'Layout mode: tap an empty tile to move the selected building.':'Layout mode off.');};$('#zoomIn').onclick=()=>{zoom=Math.min(1.35,zoom+.1);draw()};$('#zoomOut').onclick=()=>{zoom=Math.max(.75,zoom-.1);draw()};$('#tipClose').onclick=()=>$('#mapTip').classList.add('hidden');$('#workerToast button').onclick=collectAll;$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$('#closePanel').onclick=()=>$('#rightPanel').classList.remove('open');$('#soundBtn').onclick=()=>notify('Ambient audio is off in this preview.');$('#helpBtn').onclick=helpModal;document.querySelectorAll('.res-plus').forEach(b=>b.onclick=()=>notify('Earn resources by collecting, completing jobs, and winning turf battles.'));
