function renderPanel(){if(selected){let b=state.buildings.find(o=>o.id===selected);if(b){renderBuilding(b);return}}panel('Your Empire',`<div class="welcome-card"><div class="card-kicker">YOUR STORY STARTS HERE</div><h3>One block at a time.</h3><p>Build smart, keep a low profile, and grow your Southside operation.</p></div><div class="section-title">DAILY OBJECTIVES <button onclick="window.showToast('More jobs unlock as your HQ grows.')">VIEW ALL ↗</button></div><div class="mission-card"><div class="mission-icon">⌂</div><div class="mission-copy"><strong>Build your network</strong><small>Own 5 facilities (${state.buildings.length}/5)</small><div class="progress-track"><span style="width:${Math.min(100,state.buildings.length/5*100)}%"></span></div></div><span class="mission-reward">+$250</span></div><div class="mission-card"><div class="mission-icon">✦</div><div class="mission-copy"><strong>Make a name</strong><small>Reach 200 reputation (${state.rep}/200)</small><div class="progress-track"><span style="width:${Math.min(100,state.rep/2)}%"></span></div></div><span class="mission-reward">+40 ★</span></div><div class="section-title">BLOCK STATUS</div><div class="status-row"><span>Territory secured</span><strong>${state.buildings.length} / 8 sites</strong></div><div class="status-row"><span>Available crew</span><strong>${state.units} operators</strong></div><div class="status-row"><span>Battle trophies</span><strong>♛ ${state.trophies}</strong></div><div class="attack-card"><small>THE STREETS ARE OPEN</small><h3>Find a rival crew</h3><p>Scout a neighborhood, make your move, and bring home the take.</p><button class="primary-btn" onclick="window.openRaid()">Scout targets&nbsp; →</button></div><div class="section-title">NEIGHBORHOOD HEAT</div><div class="status-row"><span>Suspicion level</span><strong>${state.heat}%</strong></div><div class="status-row"><span>Next patrol check</span><strong>IN ${Math.max(1,Math.floor((state.raidAt-Date.now())/60000))} MIN</strong></div>`)}
function renderBuilding(b){const d=defs[b.type],rate=buildingRate(b),upgradeCost={cash:Math.round(180*b.level*(b.type==='hq'?2:1)),supplies:Math.round(45*b.level)};let upgrading=b.upgradeAt>0;let html=`<div class="building-card"><div class="building-card-top"><div class="building-emoji">${d.icon}</div><div class="building-name"><strong>${d.name}</strong><small>${d.kind.toUpperCase()} FACILITY</small></div><span class="level-badge">LVL ${b.level}</span></div><p class="building-desc">${d.desc}</p><div class="stat-grid"><div class="stat-box"><small>${rate?'OUTPUT / MIN':'STORED'}</small><strong>${rate?Math.floor(rate)+' harvest':money(b.stored||0)}</strong></div><div class="stat-box"><small>CAPACITY</small><strong>${rate?money(60*b.level):'—'}</strong></div></div>${b.paused?'<div class="panel-note" style="color:#e39a71">Temporarily shut down after a patrol sweep.</div>':''}</div>${rate?`<div class="status-row"><span>Ready to collect</span><strong>✳ ${money(Math.floor(b.stored))}</strong></div><button class="panel-action" onclick="window.collect(${b.id})">Collect harvest</button>`:''}${b.paused?`<button class="panel-action secondary" onclick="window.resume(${b.id})">Resume operations · $75</button>`:''}${upgrading?`<div class="timer-line"><span>UPGRADE IN PROGRESS</span><span id="upgradeCountdown">${timeLeft(b.upgradeAt)}</span></div><div class="progress-track"><span style="width:${Math.max(5,100-(b.upgradeAt-Date.now())/10000)}%"></span></div>`:`<button class="panel-action ${rate?'secondary':''}" onclick="window.upgrade(${b.id})">Upgrade to level ${b.level+1} · $${upgradeCost.cash} + ◈${upgradeCost.supplies}</button><p class="panel-note">Takes ${Math.max(10,30*b.level)} seconds · improves ${rate?'production output':'facility strength'}</p>`}${b.type==='hq'?`<div class="section-title">NEXT MILESTONE</div><div class="status-row"><span>Small-Time Operator</span><strong>${state.hq>=2?'UNLOCKED':'HQ LEVEL 2'}</strong></div>`:''}<div class="section-title">CREW ASSIGNMENT</div>${crewAssignment(b)}`;panel(d.name,html)}
function crewAssignment(b){const c=Object.entries(state.crew).find(([,id])=>id===b.type);return `<div class="status-row"><span>${c?c[0].toUpperCase():'No specialist assigned'}</span><button class="assign-btn" onclick="window.assignCrew('${b.type}')">${c?'MANAGE':'ASSIGN CREW'}</button></div>`}
function timeLeft(at){const s=Math.max(0,Math.ceil((at-Date.now())/1000));return s<60?s+'s':Math.floor(s/60)+'m '+s%60+'s'}

