function timeLeft(at){const s=Math.max(0,Math.ceil((at-Date.now())/1000));return s<60?s+'s':Math.floor(s/60)+'m '+s%60+'s'}
function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open')}function closeModal(){$('#modalBackdrop').classList.remove('open')}
function openBuild(){let opts=['grow','greenhouse','warehouse','lab','security'];openModal(`<div class="modal-kicker">EXPAND YOUR FOOTPRINT</div><h2>Build a facility</h2><p>Choose an operation to place in your territory. Facilities create new opportunities—and a little more attention.</p>${opts.map(k=>{let d=defs[k];return `<div class="build-option" onclick="window.chooseBuild('${k}')"><div class="building-emoji">${d.icon}</div><div class="build-option-copy"><strong>${d.name}</strong><small>${d.kind==='production'?'Produces harvest over time':d.kind==='storage'?'Secure storage and capacity':'Supports your operation'}</small></div><div class="build-cost">$${d.cost.cash}<em>◈ ${d.cost.supplies}</em></div></div>`}).join('')}<button class="modal-action" onclick="window.closeBuild()">Cancel</button>`)}
window.chooseBuild=type=>{let d=defs[type];if(state.cash<d.cost.cash||state.supplies<d.cost.supplies)return notify('Not enough resources for this facility.');closeModal();placing={type,x:6,y:6};$('#mapTip').classList.remove('hidden');notify('Tap an empty tile to place your '+d.name+'.');draw()};window.closeBuild=closeModal;
window.collect=id=>{let b=state.buildings.find(o=>o.id===id);if(!b||b.stored<1)return notify('Nothing ready to collect yet.');let amount=Math.floor(b.stored);b.stored-=amount;state.harvest+=amount;state.cash+=Math.floor(amount*.18);state.heat=Math.min(100,state.heat+1);refresh();save();notify(`Collected ${amount} harvest and $${Math.floor(amount*.18)}. `);renderBuilding(b)};
function collectAll(){let amount=0;for(const b of state.buildings){if(defs[b.type].kind==='production'){amount+=Math.floor(b.stored);b.stored=0}}if(!amount)return notify('Your crew is still working. Check back soon.');state.harvest+=amount;state.cash+=Math.floor(amount*.18);refresh();save();notify(`Crew collected ${amount} harvest and $${Math.floor(amount*.18)}.`);if(selected)renderPanel()}
window.collectAll=collectAll;window.upgrade=id=>{let b=state.buildings.find(o=>o.id===id);if(!b||b.upgradeAt)return;let cash=Math.round(180*b.level*(b.type==='hq'?2:1)),supplies=Math.round(45*b.level);if(state.cash<cash||state.supplies<supplies)return notify('You need more cash or supplies.');state.cash-=cash;state.supplies-=supplies;b.upgradeAt=Date.now()+Math.max(10000,30000*b.level);refresh();save();renderBuilding(b);notify('Your crew started the upgrade.');};window.resume=id=>{let b=state.buildings.find(o=>o.id===id);if(!b||state.cash<75)return notify('You need $75 to restart operations.');state.cash-=75;b.paused=false;refresh();save();renderBuilding(b);notify('Operations are back online.')};
window.assignCrew=type=>{const names={grow:'The Grower',lab:'The Chemist',warehouse:'The Dealer',hq:'The Engineer',security:'The Enforcer'},key={grow:'grower',lab:'chemist',warehouse:'dealer',hq:'engineer',security:'enforcer'}[type];if(!key)return notify('This facility has no specialist role.');let k=key;openModal(`<div class="modal-kicker">SPECIALIST CREW</div><h2>${names[type]}</h2><p>Assign a specialist to increase the effectiveness of the matching facility. Each specialist can oversee one location.</p><div class="crew-card"><div class="crew-avatar">${({grow:'🌿',lab:'⚗️',warehouse:'💼',hq:'🔧',security:'🛡️'})[type]}</div><div class="crew-meta"><strong>${names[type]}</strong><small>${({grow:'Boosts harvest production by 25%.',lab:'Speeds up research and unlocks.',warehouse:'Improves collection income.',hq:'Reduces construction timers.',security:'Keeps neighborhood heat in check.'})[type]}</small></div></div><button class="modal-action" onclick="window.confirmAssign('${k}','${type}')">${state.crew[k]===type?'Already assigned':'Assign to this facility'}</button>`)};
window.confirmAssign=(key,type)=>{state.crew[key]=type;closeModal();if(key==='grow')state.heat=Math.max(0,state.heat-3);save();renderPanel();notify('Specialist assigned. Your crew is more effective.')};
function renderSpecialView(view){if(view==='crew'){panel('Operations',`<div class="welcome-card"><div class="card-kicker">YOUR INNER CIRCLE</div><h3>Good people. Quiet work.</h3><p>Assign specialists to facilities and train a crew for territory runs.</p></div><div class="section-title">SPECIALISTS</div>${[['grower','🌿','The Grower','+25% production at grow facilities'],['chemist','⚗️','The Chemist','Research operations specialist'],['dealer','💼','The Dealer','Improves business income'],['engineer','🔧','The Engineer','Cuts future build timers'],['enforcer','🛡️','The Enforcer','Lowers heat and guards your turf']].map(([key,icon,name,desc])=>`<div class="crew-card"><div class="crew-avatar">${icon}</div><div class="crew-meta"><strong>${name}</strong><small>${desc}</small></div><span class="level-badge">${state.crew[key]?'ASSIGNED':'READY'}</span></div>`).join('')}<div class="section-title">FIELD CREW</div><div class="status-row"><span>Operators ready</span><strong>♟ ${state.units}</strong></div><div class="status-row"><span>Trained this week</span><strong>${state.trained}</strong></div><button class="panel-action" onclick="window.trainUnits()">Train 3 operators · $180</button><p class="panel-note">A bigger crew can make more of a rival's territory run.</p><div class="section-title">UNIT ROSTER</div><div class="crew-card"><div class="crew-avatar">🏃</div><div class="crew-meta"><strong>Runners</strong><small>Quick and quiet. Better at securing supplies.</small></div><span class="level-badge">×${state.units}</span></div><div class="crew-card"><div class="crew-avatar">🧰</div><div class="crew-meta"><strong>Fixers</strong><small>Sturdy operators who keep a run on track.</small></div><span class="level-badge">UNLOCK HQ 2</span></div>`)}else if(view==='research'){panel('Research',`<div class="welcome-card"><div class="card-kicker">THE THINK TANK</div><h3>Stay one step ahead.</h3><p>Invest supplies to improve operations, defense, and your crew's capabilities.</p></div><div class="section-title">DEVELOPMENT TREE <span>LEVEL ${state.hq}</span></div>${[['efficient','⌬','Efficient routines','Increase production output by 15%.',120],['reinforced','⬡','Reinforced storage','Protect more goods during a turf run.',160],['quiet','◉','Low-profile systems','Reduce heat gained from expansion.',180],['network','✦','Neighborhood network','Unlock new building sites at HQ level 2.',280]].map(([key,icon,title,desc,cost],i)=>`<div class="tree-node ${i>1&&state.hq<2?'locked':''}"><div class="tree-node-top"><span class="tree-icon">${icon}</span><strong>${title}</strong><span class="level-badge">${state.research[key]?'DONE':'TIER '+(i+1)}</span></div><p>${desc}</p><button onclick="window.research('${key}',${cost})" ${state.research[key]||i>1&&state.hq<2?'disabled':''}>${state.research[key]?'COMPLETED':`Unlock · ◈ ${cost}`}</button></div>`).join('')}<div class="section-title">SUPPLIES AVAILABLE <span>◈ ${money(state.supplies)}</span></div>`)}else{panel('Intel',`<div class="welcome-card"><div class="card-kicker">THE STREET NETWORK</div><h3>Know your next move.</h3><p>Scout nearby crews, find an opening, and bring home a clean win.</p></div><div class="section-title">AVAILABLE TURF</div>${[['The Rust Dogs','⚙',340,28,2],['Cinder Block Crew','◈',520,46,3],['East Ward Outfit','✦',760,63,4]].map(([name,icon,loot,guard,tier])=>`<div class="rival-card"><div class="rival-avatar">${icon}</div><div class="crew-meta"><strong>${name}</strong><small>HQ ${tier} · ${guard} guard strength</small><div class="rival-stats"><span>+$${loot}</span><span>+${Math.floor(loot/12)} REP</span></div></div><button onclick="window.launchRaid('${name}',${loot},${guard})">SCOUT</button></div>`).join('')}<div class="section-title">YOUR RECORD</div><div class="status-row"><span>Victories</span><strong>${state.trophies}</strong></div><div class="status-row"><span>Current streak</span><strong>—</strong></div><div class="status-row"><span>Territory rank</span><strong>#${Math.max(1,1284-state.trophies)}</strong></div><p class="panel-note">Rivals are simulated crews. Multiplayer is not connected in this build.</p>`)}}
window.trainUnits=()=>{if(state.cash<180)return notify('Not enough cash to train your crew.');state.cash-=180;state.units+=3;state.trained+=3;refresh();save();renderSpecialView('crew');notify('Three operators joined your crew.')};window.research=(key,cost)=>{if(state.research[key])return;if(state.supplies<cost)return notify('Not enough supplies for this research.');state.supplies-=cost;state.research[key]=true;if(key==='efficient')state.buildings.forEach(b=>{if(defs[b.type].kind==='production')b.stored=Math.min(b.stored+15*b.level,60*b.level)});if(key==='quiet')state.heat=Math.max(0,state.heat-12);refresh();save();renderSpecialView('research');notify('Research unlocked. New edge acquired.')};
function helpModal(){openModal(`<div class="modal-kicker">QUICK FIELD GUIDE</div><h2>Build smart. Stay sharp.</h2><p>Your goal is to grow the Southside operation while managing heat and defending your turf. This is a fictional strategy game—rival crews and production are abstracted.</p><div class="status-row"><span>1 · Build</span><strong>Expand with the ＋ Build button.</strong></div><div class="status-row"><span>2 · Collect</span><strong>Tap a production site to collect.</strong></div><div class="status-row"><span>3 · Upgrade</span><strong>Invest cash and supplies for levels.</strong></div><div class="status-row"><span>4 · Compete</span><strong>Scout rivals in Intel and Operations.</strong></div><div class="status-row"><span>5 · Keep cool</span><strong>Security facilities reduce neighborhood heat.</strong></div><button class="modal-action" onclick="window.closeBuild()">Got it</button>`)}
window.openRaid=()=>{selectedView='intel';renderSpecialView('intel');$('#rightPanel').classList.add('open')};

