="section-title">DEVELOPMENT TREE <span>LEVEL ${state.hq}</span></div>${[['efficient','⌬','Efficient routines','Increase production output by 15%.',120],['reinforced','⬡','Reinforced storage','Protect more goods during a turf run.',160],['quiet','◉','Low-profile systems','Reduce heat gained from expansion.',180],['network','✦','Neighborhood network','Unlock new building sites at HQ level 2.',280]].map(([key,icon,title,desc,cost],i)=>`<div class="tree-node ${i>1&&state.hq<2?'locked':''}"><div class="tree-node-top"><span class="tree-icon">${icon}</span><strong>${title}</strong><span class="level-badge">${state.research[key]?'DONE':'TIER '+(i+1)}</span></div><p>${desc}</p><button onclick="window.research('${key}',${cost})" ${state.research[key]||i>1&&state.hq<2?'disabled':''}>${state.research[key]?'COMPLETED':`Unlock · ◈ ${cost}`}</button></div>`).join('')}<div class="section-title">SUPPLIES AVAILABLE <span>◈ ${money(state.supplies)}</span></div>`)}else{panel('Intel',`<div class="welcome-card"><div class="card-kicker">THE STREET NETWORK</div><h3>Know your next move.</h3><p>Scout nearby crews, find an opening, and bring home a clean win.</p></div><div class="section-title">AVAILABLE TURF</div>${[['The Rust Dogs','⚙',340,28,2],['Cinder Block Crew','◈',520,46,3],['East Ward Outfit','✦',760,63,4]].map(([name,icon,loot,guard,tier])=>`<div class="rival-card"><div class="rival-avatar">${icon}</div><div class="crew-meta"><strong>${name}</strong><small>HQ ${tier} · ${guard} guard strength</small><div class="rival-stats"><span>+$${loot}</span><span>+${Math.floor(loot/12)} REP</span></div></div><button onclick="window.launchRaid('${name}',${loot},${guard})">SCOUT</button></div>`).join('')}<div class="section-title">YOUR RECORD</div><div class="status-row"><span>Victories</span><strong>${state.trophies}</strong></div><div class="status-row"><span>Current streak</span><strong>—</strong></div><div class="status-row"><span>Territory rank</span><strong>#${Math.max(1,1284-state.trophie