window.openRaid=()=>{selectedView='intel';renderSpecialView('intel');$('#rightPanel').classList.add('open')};
window.launchRaid=(name,loot,guard)=>{battle={name,loot,guard,deployed:0};openModal(`<div class="modal-kicker">INTEL REPORT · ${name.toUpperCase()}</div><h2>Make your move.</h2><p>Rival crew spotted. Pick how many operators to send. A stronger crew improves your chances; expect a little neighborhood heat either way.</p><div class="battle-arena"><div class="battle-hq">🏚️</div><div class="battle-hp"><i></i></div><div class="battle-unit u1">🏃</div><div class="battle-unit u2">🧢</div><div class="battle-unit u3">🧰</div></div><div class="status-row"><span>Estimated take</span><strong>💵 $${loot} · ★ ${Math.floor(loot/12)} rep</strong></div><div class="status-row"><span>Rival guard</span><strong>🛡 ${guard} strength</strong></div><div class="unit-pick"><span>🏃</span><div><strong>Runners</strong><small>Available operators: ${state.units}</small></div><button onclick="window.deployCrew()">DEPLOY 3</button></div><button class="modal-action" onclick="window.startBattle()">Start turf run →</button>`)};
window.deployCrew=()=>{if(!battle)return;if(state.units-battle.deployed<3)return notify('You need at least 3 available operators.');battle.deployed+=3;notify(`${battle.deployed} operators ready.`)};
window.startBattle=()=>{if(!battle)return;if(!battle.deployed){if(state.units<3)return notify('Train at least 3 operators first.');battle.deployed=3}state.units-=battle.deployed;const winPower=battle.deployed*(1+(state.research.reinforced?.08:0));const chance=Math.max(.2,Math.min(.94,.38+winPower/(battle.guard*2.7)));const win=Math.random()<chance;const target=battle;openModal(`<div class="modal-kicker">FIELD REPORT · ${target.name.toUpperCase()}</div><h2>Operation underway</h2><p>Your crew is moving through the neighborhood. Sit tight while the window is open.</p><div class="battle-arena"><div class="battle-hq">🏚️</div><div class="battle-hp"><i style="animation:advance 1s infinite alternate;width:60%"></i></div><div class="battle-unit u1">🏃</div><div class="battle-unit u2">🧢</div><div class="battle-unit u3">🧰</div></div><div class="status-row"><span>Operators deployed</span><strong>${battle.deployed}</strong></div><div class="status-row"><span>Signal</span><strong style="color:#b4d878">CREW IN MOTION...</strong></div>`);setTimeout(()=>{if(win){state.cash+=target.loot;state.harvest+=Math.floor(target.loot*.38);state.rep+=Math.floor(target.loot/12);state.trophies++;state.heat=Math.min(100,state.heat+Math.floor(target.loot/35));}else{state.heat=Math.min(100,state.heat+10);state.rep=Math.max(0,state.rep-3)}state.units+=Math.floor(battle.deployed*.55);battle=null;refresh();save();openModal(`<div class="battle-result"><div class="result-icon">${win?'🏆':'🌫️'}</div><div class="modal-kicker">FIELD REPORT</div><h2>${win?'Clean work.':'Close call.'}</h2><p>${win?'Your crew secured the block and slipped away before the patrol rolled through.':'Rival guards pushed your crew back. Your operators regrouped, but the take got away.'}</p>${win?`<div class="battle-reward"><span>💵 +$${target.loot}</span><span>✳ +${Math.floor(target.loot*.38)}</span><span>★ +${Math.floor(target.loot/12)}</span></div>`:`<div class="battle-reward"><span>HEAT +10</span><span>REP −3</span></div>`}<p>Operators returned: ${Math.floor((win?battle?.deployed||3:3)*.55)} · Your crew is regrouping.</p><button class="modal-action" onclick="window.closeBuild();window.showToast('${win?'Victory. Your reputation is climbing.':'Crew regrouped. Try again when ready.'}')">Back to the block</button></div>`);renderPanel()},1800);refresh();save()};
window.showToast=notify;
window.addEventListener('beforeunload',save);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
})();

